-- Agreed tests (verification step 2, plain SQL on PostgreSQL) for AdventureWorks2025 Production.vProductAndDescription.
-- GENERATED by npm run agreed-tests -- --object Production.vProductAndDescription. Do not edit by hand: change the fixed cases
-- in the object's spec, recapture, and review tests/AdventureWorks2025/Production.vProductAndDescription.expected.json.
-- Expected results were captured from the original T-SQL on SQL Server and are reviewed at step 5.
-- Row order is not asserted here (multiset comparison); step 3 checks order where the source guarantees one.
-- Prerequisites: the spec's tables created and the final conversion deployed.
-- Each case is one transaction and always rolls back.

-- @case 1: two products sharing a model fan out over its three described cultures; char(6) culture codes padded; '' and trailing-space descriptions kept; no model, no cultures or a missing description drops the row
BEGIN;
DELETE FROM production.product;
DELETE FROM production.product_description;
DELETE FROM production.product_model;
DELETE FROM production.product_model_product_description_culture;
INSERT INTO production.product ("ProductID", "Name", "ProductModelID") VALUES
  ('1', 'Bike', '1'),
  ('2', 'Helmet', NULL),
  ('3', 'Chain', '2'),
  ('4', 'Bike Frame', '1');
INSERT INTO production.product_description ("ProductDescriptionID", "Description") VALUES
  ('10', 'Light, stiff frame'),
  ('11', ''),
  ('12', 'Cadre léger '),
  ('13', 'Orphan model text');
INSERT INTO production.product_model ("ProductModelID", "Name") VALUES
  ('1', 'Road-150'),
  ('2', 'Chain'),
  ('3', 'Orphan');
INSERT INTO production.product_model_product_description_culture ("ProductModelID", "ProductDescriptionID", "CultureID") VALUES
  ('1', '10', 'en'),
  ('1', '12', 'fr'),
  ('1', '11', 'zh-cht'),
  ('1', '99', 'de'),
  ('3', '13', 'ar');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM production.v_product_and_description;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['ProductID', 'Name', 'ProductModel', 'CultureID', 'Description']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 two products sharing a model fan out over its three described cultures; char(6) culture codes padded;…', got, ARRAY['ProductID', 'Name', 'ProductModel', 'CultureID', 'Description']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', 'Bike', 'Road-150', 'en    ', 'Light, stiff frame'),
  ('4', 'Bike Frame', 'Road-150', 'en    ', 'Light, stiff frame'),
  ('1', 'Bike', 'Road-150', 'fr    ', 'Cadre léger '),
  ('4', 'Bike Frame', 'Road-150', 'fr    ', 'Cadre léger '),
  ('1', 'Bike', 'Road-150', 'zh-cht', ''),
  ('4', 'Bike Frame', 'Road-150', 'zh-cht', '');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 two products sharing a model fan out over its three described cultures; char(6) culture codes padded;…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
